def carry_over(apps, schema_editor):  # type: ignore[no-untyped-def]
    """Bonuses and advances already typed become named lines; payments keep their amount as
    base; salaried staff are declared (contributions stay off until the owner turns them on)."""
    schema_editor.execute("SET LOCAL app.bypass_rls = 'on'")
    PayLine = apps.get_model("staff", "PayLine")
    StaffPayment = apps.get_model("staff", "StaffPayment")
    StaffMember = apps.get_model("staff", "StaffMember")
    for line in PayLine.all_tenants.all():
        items = []
        if line.bonuses:
            items.append(
                {"label": "Primes", "amount": line.bonuses, "kind": "gain", "taxable": True}
            )
        if line.advances:
            items.append(
                {"label": "Avances", "amount": line.advances, "kind": "deduction", "taxable": False}
            )
        line.items = items
        line.gross = line.base + line.bonuses
        line.net = line.gross - line.advances
        line.save(update_fields=["items", "gross", "net"])
    for payment in StaffPayment.all_tenants.all():
        payment.base = payment.amount
        payment.save(update_fields=["base"])
    StaffMember.all_tenants.filter(kind="employee").update(declared=True)


